{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Niraparib absolute oral bioavailability in cancer patients was 72.7% (90% CI 61.69–83.40) after a 300 mg oral dose versus IV 14C-niraparib, well above the 20% threshold."
    },
    {
      "card_ids": ["C19"],
      "claim": "Fenspiride absolute oral bioavailability in 12 healthy volunteers was 90 (9)% for an 80 mg slow-release tablet versus IV, strongly supporting high bioavailability."
    },
    {
      "card_ids": ["C20"],
      "claim": "Thalidomide absolute oral bioavailability in fasting healthy volunteers was probably high (80–100% at low doses) for 100 mg tablets or capsules, above the 20% threshold."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All informative evidence molecules with high assay-transfer scores show oral bioavailability at or above 20%, mostly well above, so the prediction is high.",
  "evidence_gaps": [
    "Molecule 8 has a provenance conflict: C04 refers to stavudine while C47 and C31 refer to didanosine/ddA; these inconsistent cards were discounted.",
    "Some low-F records are from altered conditions (C07 pediatric antacid solution, C12 infant enteral) or qualitative (C08) and were not used as negative evidence.",
    "Gaboxadol evidence (C49) is qualitative 'high' without a numeric F value."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C24", "C19", "C20"],
  "revision_action": "initial",
  "supportive_card_ids": ["C24", "C19", "C20"]
}

